export const CAROUSEL_ASPECTS = ["4:5", "3:4", "1:1", "9:16"] as const;

export type CarouselAspect = (typeof CAROUSEL_ASPECTS)[number];

export type CarouselDimensions = { width: number; height: number };

export const DEFAULT_CAROUSEL_ASPECT: CarouselAspect = "4:5";

export const CAROUSEL_ASPECT_DIMENSIONS: Record<
  CarouselAspect,
  CarouselDimensions
> = {
  "4:5": { width: 1080, height: 1350 },
  "3:4": { width: 1080, height: 1440 },
  "1:1": { width: 1080, height: 1080 },
  "9:16": { width: 1080, height: 1920 },
};

export function isCarouselAspect(value: unknown): value is CarouselAspect {
  return CAROUSEL_ASPECTS.some((aspect) => aspect === value);
}

export function resolveCarouselDimensions(
  aspect: CarouselAspect | undefined
): CarouselDimensions {
  return CAROUSEL_ASPECT_DIMENSIONS[aspect ?? DEFAULT_CAROUSEL_ASPECT];
}

export function findCarouselAspectByDimensions(
  dimensions: CarouselDimensions
): CarouselAspect | null {
  return (
    CAROUSEL_ASPECTS.find((aspect) => {
      const expected = CAROUSEL_ASPECT_DIMENSIONS[aspect];
      return (
        expected.width === dimensions.width &&
        expected.height === dimensions.height
      );
    }) ?? null
  );
}
